// PARSE LIVE VK ITEMS (inert until the HTTP placeholder is enabled by the operator).
// With the HTTP node disabled, items pass through WITHOUT a VK API response body — this node then throws,
// guaranteeing no fabricated posts/comments can enter the pipeline. Handles BOTH methods:
//   wall.get        -> resp.items are POSTS
//   wall.getComments -> resp.items are COMMENTS (public consumer demand)
// PUBLIC data only: profile_url is derivable only for user authors (from_id>0); no member extraction, no hidden
// contacts, aggregate author counts happen downstream.
function str(v){return v==null?'':String(v).trim();}
function msk(ts){var m=new Date(ts*1000+10800000);return m.toISOString().replace('Z','+03:00');}
const out=[];
for(const it of $input.all()){
  const j=it.json;
  const resp=j.response||((j.body||{}).response);
  if(!resp||!Array.isArray(resp.items)){
    throw new Error('WF13 live parse: no VK API response received — the HTTP placeholder node is DISABLED (inert by design, DEC-125). Enable it with a bound credential only after operator approval; default runs use fixture mode.');
  }
  const method=str(j.method)||'wall.get';
  const maxItems=Math.min(Number(j.max_items)||10,10);
  let count=0;
  if(method==='wall.getComments'){
    const ownerId=str(j.owner_id);          // e.g. -111222
    const postId=str(j.post_id);            // e.g. 301
    const group='wall'+ownerId+'_'+postId;
    for(const c of resp.items){
      if(count>=maxItems)break;
      const text=str(c.text); if(!text)continue; count++;
      const fromId=Number(c.from_id)||0;
      out.push({ json: {
        group:group, group_title:group, item_type:'comment', item_id:postId, comment_id:String(c.id||''),
        item_url:'https://vk.com/wall'+ownerId+'_'+postId+'?reply='+String(c.id||''),
        author_handle:(fromId>0?('id'+fromId):('club'+Math.abs(fromId))),
        author_name:'', author_profile_public:(fromId>0),
        published_at:(c.date?msk(Number(c.date)):''), text:text } });
    }
  } else {
    const group=str(j.screen_name)||'unknown';
    for(const p of resp.items){
      if(count>=maxItems)break;
      const text=str(p.text); if(!text)continue; count++;
      const ownerId=String(p.owner_id||'');
      const fromId=Number(p.from_id)||0;
      out.push({ json: {
        group:group, group_title:group, item_type:'post', item_id:String(p.id||''), comment_id:'',
        item_url:'https://vk.com/wall'+ownerId+'_'+String(p.id||''),
        author_handle:(fromId>0?('id'+fromId):('club'+Math.abs(fromId))),
        author_name:'', author_profile_public:(fromId>0),
        published_at:(p.date?msk(Number(p.date)):''), text:text } });
    }
  }
}
if(!out.length){ throw new Error('WF13 live parse: 0 usable items parsed — check allowlist / API response before retrying.'); }
return out;

